import os
from typing import Dict, List, Any

import requests


AZURE_CONTENT_SAFETY_ENDPOINT = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT", "").rstrip("/")
AZURE_CONTENT_SAFETY_KEY = os.getenv("AZURE_CONTENT_SAFETY_KEY", "")
AZURE_CONTENT_SAFETY_API_VERSION = os.getenv("AZURE_CONTENT_SAFETY_API_VERSION", "2023-10-01")
AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD = int(os.getenv("AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD", "2"))


def _headers() -> Dict[str, str]:
    return {
        "Content-Type": "application/json",
        "Ocp-Apim-Subscription-Key": AZURE_CONTENT_SAFETY_KEY,
    }


def _analyze_text(text: str) -> Dict[str, Any]:
    if not AZURE_CONTENT_SAFETY_ENDPOINT or not AZURE_CONTENT_SAFETY_KEY:
        raise RuntimeError(
            "Azure Content Safety configuration missing. Set AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY."
        )

    url = (
        f"{AZURE_CONTENT_SAFETY_ENDPOINT}/contentsafety/text:analyze"
        f"?api-version={AZURE_CONTENT_SAFETY_API_VERSION}"
    )
    payload = {"text": text, "categories": ["Hate", "SelfHarm", "Sexual", "Violence"]}

    response = requests.post(url, headers=_headers(), json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def allow_text(text: str, category_thresholds: Dict[str, int] = None) -> bool:
    """
    Returns True if the text is allowed under the configured category thresholds, otherwise False.
    Thresholds are severity levels from 0 to 4.
    """
    if category_thresholds is None:
        category_thresholds = {
            "Hate": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "SelfHarm": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "Sexual": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "Violence": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
        }

    result = _analyze_text(text)
    categories = result.get("categoriesAnalysis", [])

    for category in categories:
        category_name = category.get("category")
        severity = category.get("severity", 0)
        threshold = category_thresholds.get(category_name)
        if threshold is not None and severity >= threshold:
            return False

    return True


def allow_text_with_details(text: str, category_thresholds: Dict[str, int] = None) -> Dict[str, Any]:
    """
    Returns a structured moderation decision with category severities.
    """
    if category_thresholds is None:
        category_thresholds = {
            "Hate": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "SelfHarm": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "Sexual": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            "Violence": AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
        }

    result = _analyze_text(text)
    categories = result.get("categoriesAnalysis", [])

    violations: List[Dict[str, Any]] = []
    for category in categories:
        category_name = category.get("category")
        severity = category.get("severity", 0)
        threshold = category_thresholds.get(category_name)
        if threshold is not None and severity >= threshold:
            violations.append(
                {
                    "category": category_name,
                    "severity": severity,
                    "threshold": threshold,
                }
            )

    return {
        "allowed": len(violations) == 0,
        "violations": violations,
        "raw": result,
    }
